const { chromium } = require('playwright');
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

(async () => {
  // Fetch axe-core if not already present
  const axePath = '/tmp/axe.min.js';
  if (!fs.existsSync(axePath)) {
    execSync(`curl -sSfLo ${axePath} https://cdn.jsdelivr.net/npm/axe-core/axe.min.js`, { stdio: 'pipe' });
  }

  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const results = await page.evaluate(async () => window.axe.run());
  await browser.close();

  // Separate WCAG from best-practice violations
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  const summary = {
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      targets: v.nodes.map(n => n.target)
    }))
  };

  console.log(JSON.stringify(summary, null, 2));
  process.exit(wcag.length > 0 ? 1 : 0);
})();

