   background-color: #1a1a1a;
   color: #e0e0e0;
   font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
   font-size: 16px;
   line-height: 1.6;
 }

 main {
   padding: 2rem 1rem;
 }

 .container {
   max-width: 800px;
   margin: 0 auto;
 }

 h1 {
   color: #ffffff;
   margin-bottom: 2rem;
   font-size: 2rem;
   text-align: center;
 }

 h2 {
   margin: 0;
   font-size: 1rem;
 }

 .example {
   margin-bottom: 1.5rem;
   border: 1px solid #333;
   border-radius: 8px;
   overflow: hidden;
   background-color: #242424;
   transition: background-color 0.2s ease;
 }

 .example:hover {
   background-color: #2d2d2d;
 }

 button {
   width: 100%;
   padding: 1rem;
   background-color: transparent;
   border: none;
   color: #ffffff;
   font-size: 1rem;
   font-weight: 500;
   cursor: pointer;
   text-align: left;
   transition: background-color 0.2s ease, color 0.2s ease;
   position: relative;
   padding-right: 2.5rem;
 }

 button:hover {
   background-color: #333;
 }

 button:focus-visible {
   outline: 2px solid #4a9eff;
   outline-offset: 2px;
 }

 button::after {
   content: '▶';
   position: absolute;
   right: 1rem;
   top: 50%;
   transform: translateY(-50%);
   transition: transform 0.3s ease;
   color: #4a9eff;
 }

 button[aria-expanded="true"]::after {
   transform: translateY(-50%) rotate(90deg);
 }

 .details {
   padding: 0 1rem;
   max-height: 0;
   overflow: hidden;
   transition: max-height 0.3s ease, padding 0.3s ease;
   background-color: #1f1f1f;
 }

 .details[hidden] {
   display: none;
 }

 button[aria-expanded="true"] + .details {
   padding: 1rem;
   max-height: 500px;
 }

 .details p {
   color: #c0c0c0;
   margin-bottom: 0;
 }

 @media (prefers-reduced-motion: reduce) {
   button::after,
   .details {
     transition: none;
   }
 }

 @media (max-width: 600px) {
   h1 {
     font-size: 1.5rem;
   }

   button {
     padding: 0.875rem;
     padding-right: 2rem;
   }

   .details {
     padding: 0 0.875rem;
   }

   button[aria-expanded="true"] + .details {
     padding: 0.875rem;
   }
 }

