  btn.addEventListener('click', () => {
    const open = btn.getAttribute('aria-expanded') === 'true';
    btn.setAttribute('aria-expanded', String(!open));
    if (open) {
      panel.setAttribute('hidden', '');
    } else {
      panel.removeAttribute('hidden');
